#include <cassert>
#include <stdexcept>

class Account {
public:
    void withdraw(long amount) {
        if (amount <= 0) throw std::invalid_argument("amount must be positive");
        if (amount > balance_ - floor_) throw std::out_of_range("withdrawal would break the invariant");
        balance_ -= amount;
        assert(balance_ >= floor_);                // class invariant
    }
private:
    long balance_{}, floor_{};
};

