int divide(int a, int b)
    pre (b != 0)
    post (r: r * b <= a)
{
    contract_assert(a >= 0);  // internal invariant of this implementation
    return a / b;
}

#include <boost/contract.hpp>

void withdraw(Account& a, long amount) {
    boost::contract::old_ptr<long> old_balance = BOOST_CONTRACT_OLDOF(a.balance());
    boost::contract::check c = boost::contract::function()
        .precondition([&] { BOOST_CONTRACT_ASSERT(amount > 0); })
        .postcondition([&] { BOOST_CONTRACT_ASSERT(a.balance() == *old_balance - amount); });
    a.apply_withdrawal(amount);
}
